// Construye un objeto `response` conforme a Open Responses.
// Envuelve la salida en {__status, cuerpo} para que `Responder` fije el codigo HTTP.

const previo = $input.first().json;

// Si `Autorizar` ya decidio rechazar, se deja pasar su respuesta tal cual.
if (previo.__status !== 200) return [{ json: previo }];

const body = previo.body ?? {};

// `crypto` no existe en el sandbox del task runner de n8n.
// El id solo tiene que ser opaco y unico, no criptografico.
const id = (prefijo) =>
  prefijo + '_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 12);

const error = (code, message, param) => [{
  json: {
    __status: 400,
    cuerpo: { error: { type: 'invalid_request_error', code, message, param } },
  },
}];

// --- Validacion ---
//
// `model` NO se exige, aunque el spec lo declare obligatorio: la plataforma real
// manda {input, stream, store} sin ese campo (ejecucion 68798). Exigirlo romperia
// el endpoint en el primer mensaje del evaluador.
//
// Tampoco se exigen `id` ni `status` en los items de ENTRADA, por lo mismo:
// la plataforma manda solo {role, type, content}.

if (body.input === undefined || body.input === null) {
  return error('missing_required_parameter', 'Falta el campo `input`.', 'input');
}

if (typeof body.input !== 'string' && !Array.isArray(body.input)) {
  return error('invalid_type', 'El campo `input` debe ser un string o un array de items.', 'input');
}

if (Array.isArray(body.input)) {
  if (body.input.length === 0) {
    return error('empty_input', 'El campo `input` no puede ser un array vacio.', 'input');
  }
  for (let i = 0; i < body.input.length; i++) {
    const item = body.input[i];
    if (!item || typeof item !== 'object') {
      return error('invalid_item', 'El item ' + i + ' de `input` no es un objeto.', 'input[' + i + ']');
    }
    if (typeof item.type !== 'string' || item.type.length === 0) {
      return error('invalid_item', 'El item ' + i + ' de `input` no declara `type`.', 'input[' + i + '].type');
    }
  }
}

// --- Lectura del input ---
// De un item de tipo message se concatena el texto de sus content parts `input_text`.
function leerInput(input) {
  if (typeof input === 'string') return input;

  const textos = [];
  for (const item of input) {
    if (typeof item.content === 'string') { textos.push(item.content); continue; }
    if (!Array.isArray(item.content)) continue;
    for (const parte of item.content) {
      if (parte && parte.type === 'input_text' && typeof parte.text === 'string') {
        textos.push(parte.text);
      }
    }
  }
  return textos.join('\n');
}

const texto = leerInput(body.input);

return [{
  json: {
    __status: 200,
    cuerpo: {
      id: id('resp'),
      object: 'response',
      created_at: Math.floor(Date.now() / 1000),
      status: 'completed',
      // El modelo lo fija el flujo, no el cliente: un `model` entrante se IGNORA
      // (ADR-0002). Devolver el que mandaron seria mentir sobre quien respondio.
      // En la fase 3 este valor pasa a ser el id real del modelo del agente.
      model: 'bano',
      output: [
        {
          id: id('msg'),
          type: 'message',
          status: 'completed',
          role: 'assistant',
          content: [{ type: 'output_text', text: 'eco: ' + texto, annotations: [] }],
        },
      ],
      usage: { input_tokens: 0, output_tokens: 0, total_tokens: 0 },
    },
  },
}];

// Compara el SHA-256 del bearer recibido contra el guardado en `bano_secretos`.
// La tabla NO guarda el token, solo su hash: quien la lea no puede autenticarse.
// SHA-256 pelado basta porque el token son 256 bits aleatorios, no una contrasena
// humana: no hay diccionario que lo contenga y la fuerza bruta es inviable.

const turno = $('Webhook').first().json;
const recibidoHash = $('Hashear bearer').first().json.bearer_sha256;

const fila = $input.all().map((i) => i.json).find((r) => r.clave === 'bearer_token_sha256');
const esperadoHash = fila ? String(fila.valor || '') : '';

// Se mira la cabecera cruda, no el hash: hashear cadena vacia tambien da un hash.
const traeCabecera = String(turno.headers?.authorization || '').trim().length > 0;

const fallo = (status, code, message) => [{
  json: {
    __status: status,
    cuerpo: { error: { type: 'invalid_request_error', code, message, param: 'Authorization' } },
  },
}];

// Sin hash guardado no se puede autenticar a nadie: culpa del servidor, no del cliente.
if (!esperadoHash) {
  return [{
    json: {
      __status: 500,
      cuerpo: {
        error: {
          type: 'server_error',
          code: 'token_no_configurado',
          message: 'El servidor no tiene configurado el token de acceso.',
          param: null,
        },
      },
    },
  }];
}

if (!traeCabecera) {
  return fallo(401, 'missing_authorization', 'Falta la cabecera Authorization: Bearer <token>.');
}

if (recibidoHash !== esperadoHash) {
  return fallo(401, 'invalid_api_key', 'El token proporcionado no es valido.');
}

return [{ json: { __status: 200, body: turno.body ?? {} } }];
